import{I as r,o as l,c as t,b6 as s,J as u,w as p,j as a,a as n}from"./chunks/framework.BUXTSoD9.js";const b=JSON.parse('{"title":"Usa Jobs to Be Done para encontrar lo que los usuarios realmente quieren lograr","description":"Comprende que los usuarios no compran funciones, sino que \\"contratan\\" tu producto para completar un progreso en un escenario especifico.","frontmatter":{"title":"Usa Jobs to Be Done para encontrar lo que los usuarios realmente quieren lograr","description":"Comprende que los usuarios no compran funciones, sino que \\"contratan\\" tu producto para completar un progreso en un escenario especifico."},"headers":[],"relativePath":"es-es/stage-1/appendix-jobs-to-be-done/index.md","filePath":"es-es/stage-1/appendix-jobs-to-be-done/index.md"}'),c={name:"es-es/stage-1/appendix-jobs-to-be-done/index.md"},g=Object.assign(c,{setup(d){const o="Aproximadamente <strong>1.5 horas</strong>";return(m,e)=>{const i=r("ChapterIntroduction");return l(),t("div",null,[e[1]||(e[1]=s('<h1 id="usa-jobs-to-be-done-para-encontrar-lo-que-los-usuarios-realmente-quieren-lograr" tabindex="-1">Usa Jobs to Be Done para encontrar lo que los usuarios realmente quieren lograr <a class="header-anchor" href="#usa-jobs-to-be-done-para-encontrar-lo-que-los-usuarios-realmente-quieren-lograr" aria-label="Permalink to “Usa Jobs to Be Done para encontrar lo que los usuarios realmente quieren lograr”">​</a></h1><p><a id="top-jtbd"></a></p><h2 id="resumen-del-capitulo" tabindex="-1">Resumen del capitulo <a class="header-anchor" href="#resumen-del-capitulo" aria-label="Permalink to “Resumen del capitulo”">​</a></h2>',3)),u(i,{duration:o,tags:["JTBD","Necesidades del usuario","Pensamiento de producto","Insight de necesidades"],coreOutput:"1 frase JTBD que se parezca mas a una necesidad real",expectedOutput:"Poder convertir una idea vaga en un escenario de usuario y una direccion MVP mas concretos"},{default:p(()=>[...e[0]||(e[0]=[a("p",null,'Muchas personas que empiezan a hacer productos cometen el error de centrar toda su atencion en "que funcionalidad voy a hacer". Ves que otros tienen clasificacion inteligente, y tu tambien quieres anadirla; ves que otros tienen resumen automatico, y tu tambien quieres integrarlo; ves que otros han hecho Agent, multimodal, workflows, y sientes que no puedes quedarte atras.',-1),a("p",null,'Pero en la realidad, los usuarios rara vez deciden usar un producto porque "el nombre de la funcion es genial". Lo que hacen es, en un momento concreto, querer avanzar en algo, y por ello "contratan" temporalmente una herramienta, un servicio, o incluso a una persona, para ayudarles a completar ese paso.',-1),a("p",null,[n("Esto es exactamente lo que el metodo "),a("strong",null,"Jobs to Be Done (JTBD)"),n(" quiere recordarnos: "),a("strong",null,"los usuarios no compran funciones en si, sino que contratan alguna solucion para ayudarles a completar un progreso.")],-1),a("p",null,"Este articulo te guiara desde cero para entender JTBD en un lenguaje lo mas claro posible, y convertirlo en una herramienta de analisis que puedas usar directamente al hacer aplicaciones de IA.",-1)])]),_:1}),e[2]||(e[2]=s(`<div class="info custom-block"><p class="custom-block-title">SOP minimo</p><p><strong>Objetivo</strong>: Despues de leer, sabras mejor como convertir una idea vaga en una necesidad con un escenario de usuario real, en lugar de tener solo un monton de nombres de funciones en la cabeza.</p><p><strong>Accion</strong>: Escribe 1 idea vaga, encuentra 3 usuarios potenciales y preguntales &quot;la ultima vez, como lo manejaste&quot;, y luego organizalo en 1 frase JTBD.</p><p><strong>Resultado</strong>: Obtendras una hipotesis de necesidad mas clara, sabiendo que debes resolver primero en la primera version.</p><p><strong>Enlaces rapidos</strong>: <a href="#jtbd-what">Que es JTBD</a> · <a href="#jtbd-formula">Formula de una frase</a> · <a href="#jtbd-ai">Como te ayuda la IA</a></p></div><h2 id="aprenderas-lo-siguiente" tabindex="-1">Aprenderas lo siguiente <a class="header-anchor" href="#aprenderas-lo-siguiente" aria-label="Permalink to “Aprenderas lo siguiente”">​</a></h2><ol><li>Que es Jobs to Be Done, y por que esta mas cerca de las necesidades reales que el &quot;brainstorming de funciones&quot;</li><li>Como distinguir entre &quot;funciones que el usuario dice querer&quot; y &quot;lo que el usuario realmente quiere lograr&quot;</li><li>Como usar una plantilla simple para descomponer una idea vaga en escenario, disparador, obstaculo y criterio de exito</li><li>Como usar JTBD en productos de IA, preguntas de entrevistas y organizacion de prompts</li></ol><p><a id="jtbd-what"></a></p><h2 id="_1-que-es-jobs-to-be-done" tabindex="-1"><a href="#top-jtbd">1. Que es Jobs to Be Done</a> <a class="header-anchor" href="#_1-que-es-jobs-to-be-done" aria-label="Permalink to “1. Que es Jobs to Be Done”">​</a></h2><p>Jobs to Be Done se abrevia comunmente como <strong>JTBD</strong>. Su idea central esta relacionada con la expresion clasica promovida por el equipo de Clayton Christensen: <strong>los usuarios &quot;contrataran&quot; un producto para completar una tarea.</strong></p><p>La &quot;tarea&quot; aqui no es una accion superficial de una lista de pendientes, sino un <strong>progreso</strong> que el usuario espera que ocurra en su estado. Por ejemplo:</p><ul><li>No es &quot;quiero una herramienta de actas con IA&quot;, sino &quot;quiero tener los puntos clave, las tareas pendientes y los responsables organizados en 10 minutos despues de la reunion, sin depender de la memoria para completar las notas&quot;</li><li>No es &quot;quiero una app de contabilidad&quot;, sino &quot;quiero saber en que se me va el dinero, para no estar ansioso a fin de mes&quot;</li><li>No es &quot;quiero un optimizador de curriculum&quot;, sino &quot;quiero enviar un curriculum decente con mas confianza, sin dudar cada vez de que lo he escrito mal&quot;</li></ul><p>Entonces, <strong>JTBD no se centra en como se ve el producto, sino en por que el usuario lo necesita en este momento.</strong></p><p>Es por eso que muchos productos aparentemente diferentes en realidad compiten por el mismo job. El usuario quiere &quot;no aburrirse en el camino al trabajo&quot;, y los objetos que puede contratar pueden ser videos cortos, podcasts, juegos, chat, o incluso echar una cabezadita. El usuario quiere &quot;entender rapidamente un PDF muy largo&quot;, y los objetos que puede contratar pueden ser una herramienta de resumen con IA, un becario, un colega, leerlo a duras penas, o simplemente no leerlo.</p><p>Una vez que miras los problemas desde esta perspectiva, descubres que tu verdadero competidor muchas veces no es solo &quot;otra app parecida a la tuya&quot;, sino <strong>todas las soluciones alternativas aceptables para el usuario</strong>.</p><h2 id="_2-en-que-se-diferencia-jtbd-de-los-perfiles-de-usuario-y-las-listas-de-funciones" tabindex="-1">2. En que se diferencia JTBD de los perfiles de usuario y las listas de funciones <a class="header-anchor" href="#_2-en-que-se-diferencia-jtbd-de-los-perfiles-de-usuario-y-las-listas-de-funciones" aria-label="Permalink to “2. En que se diferencia JTBD de los perfiles de usuario y las listas de funciones”">​</a></h2><p>Muchos principiantes, al hacer analisis de necesidades, primero escriben un perfil de usuario: 25 anos, mujer, ciudad de primer nivel, oficinista, le gustan las herramientas de eficiencia, dispuesta a probar productos nuevos. Esta informacion no se puede decir que sea completamente inutil, pero normalmente <strong>no es suficiente para explicar por que una persona tomara accion en este momento.</strong></p><p>JTBD se preocupa mas por las siguientes preguntas:</p><ul><li>En que escenario decide buscar una solucion</li><li>Que es exactamente lo que le tiene bloqueado en ese momento</li><li>Que quiere llevar al siguiente nivel</li><li>Que metodo torpe esta usando actualmente para arreglarselas</li><li>Si las cosas se resuelven bien, que resultado le hara sentir que &quot;valio la pena&quot;</li></ul><p>Es decir, <strong>el perfil de usuario es mas como &quot;quien es probablemente esta persona&quot;, mientras que JTBD es mas como &quot;que quiere realmente lograr esta persona ahora&quot;.</strong></p><p>Asimismo, las listas de funciones tambien pueden desviar a uno. El usuario dice &quot;quiero exportar a Word&quot;, &quot;quiero reescritura con IA&quot;, &quot;quiero entrada de voz&quot;; todo esto son solo expresiones superficiales. JTBD seguira preguntando:</p><ul><li>Por que necesitas exportar a Word ahora, y no a PDF?</li><li>Quieres reescribir, es porque el estilo es malo, o porque necesitas adaptarlo a diferentes destinatarios?</li><li>Quieres entrada de voz, es porque te da pereza escribir, o porque frecuentemente estas caminando, conduciendo, o necesitas registrar justo despues de una reunion?</li></ul><p>Muchas veces, <strong>la funcion es solo una traduccion temporal del job</strong>. Si solo recoges funciones, es facil hacer un producto donde &quot;agregas lo que el usuario dice&quot;; si puedes ver el job detras, tienes mas oportunidades de hacer una solucion verdaderamente comoda y competitiva.</p><h2 id="_3-un-ejemplo-que-hasta-un-principiante-puede-entender" tabindex="-1">3. Un ejemplo que hasta un principiante puede entender <a class="header-anchor" href="#_3-un-ejemplo-que-hasta-un-principiante-puede-entender" aria-label="Permalink to “3. Un ejemplo que hasta un principiante puede entender”">​</a></h2><p>Primero no te apresures a pensar en productos complejos de IA; empecemos con un ejemplo de la vida cotidiana.</p><p>Supongamos que alguien siempre llega tarde para desayunar antes de salir de casa por la manana, y a menudo compra un sandwich y un cafe en la entrada del metro. En la superficie, &quot;compra&quot; un desayuno; pero si lo miramos con JTBD, lo que realmente quiere lograr puede ser:</p><ul><li>Resolver una comida de la forma que menos esfuerzo mental requiera en una manana con prisa</li><li>Evitar llegar a la oficina muerto de hambre</li><li>No retrasar el ritmo de desplazamiento por desayunar</li></ul><p>En este caso, el usuario no esta contratando &quot;un sandwich de una marca fija&quot;, sino una solucion que le ayude a avanzar su manana sin problemas. Si la tienda de conveniencia de al lado es mas rapida, mas cercana y mas estable, probablemente cambiara inmediatamente su eleccion.</p><p>Llevando esta logica a productos de IA es aun mas evidente.</p><p>Por ejemplo, si quieres hacer una &quot;herramienta de actas de reuniones con IA&quot;. Si te quedas solo en el nivel de funciones, facilmente empezaras a pensar:</p><ul><li>Deberia soportar la subida de audio?</li><li>Deberia integrar separacion de hablantes?</li><li>Deberia exportar a Markdown?</li><li>Deberia generar automaticamente tareas pendientes?</li></ul><p>Nada de esto esta mal, pero no es suficiente. Si preguntas un nivel mas con JTBD, lo que el usuario realmente quiere lograr puede ser:</p><ul><li>Quiero tener los resultados de la discusion sincronizados con los que no asistieron en 10 minutos despues de la reunion</li><li>Quiero extraer limpiamente las tareas, responsables y fechas limite, sin que el equipo colabore de memoria</li><li>Quiero reducir el tiempo de organizacion repetitiva de contenido de reuniones, guardando energia para la toma de decisiones y el avance</li></ul><p>Una vez que el job queda claro, muchas prioridades de funciones aparecen automaticamente. Lo mas importante en la primera version puede no ser &quot;soportar 12 formatos de exportacion&quot;, sino:</p><ul><li>La estructura del acta debe ser suficientemente clara</li><li>La extraccion de tareas pendientes debe ser estable</li><li>Compartir el enlace debe ser facil</li><li>El resultado debe ser lo suficientemente confiable para reenviarlo directamente al equipo</li></ul><p>Este es el valor de JTBD: <strong>te ayuda a volver de &quot;que capacidades quiero apilar&quot; a &quot;que progreso quiero ayudar al usuario a alcanzar&quot;.</strong></p><h2 id="_4-una-plantilla-jtbd-util" tabindex="-1">4. Una plantilla JTBD util <a class="header-anchor" href="#_4-una-plantilla-jtbd-util" aria-label="Permalink to “4. Una plantilla JTBD util”">​</a></h2><p>Si eres principiante, primero no intentes hacer JTBD muy academico. Con capturar los 5 elementos mas practicos es suficiente.</p><h3 id="_4-1-escenario" tabindex="-1">4.1 Escenario <a class="header-anchor" href="#_4-1-escenario" aria-label="Permalink to “4.1 Escenario”">​</a></h3><p>En que momento y en que entorno el usuario piensa en este producto?</p><ul><li>Despues de una reunion</li><li>Cuando el jefe pide materiales de urgencia</li><li>Por la noche preparando el curriculum para enviar</li><li>A fin de mes descubriendo que el dinero no llega</li></ul><p><strong>Una necesidad sin escenario normalmente no es lo suficientemente real.</strong></p><h3 id="_4-2-disparador" tabindex="-1">4.2 Disparador <a class="header-anchor" href="#_4-2-disparador" aria-label="Permalink to “4.2 Disparador”">​</a></h3><p>Que le hace decidir buscar una solucion inmediatamente?</p><ul><li>Abrumado por un documento largo, sin saber por donde empezar</li><li>Tienes que entregar algo manana, y hoy descubres que el formato es un desastre</li><li>Tu jefe te acaba de preguntar por el progreso, y te das cuenta de que no lo tienes organizado</li><li>Quieres mantener un registro, pero escribir a mano, copiar y organizar es muy complicado</li></ul><p>Los disparadores suelen venir con emocion. Esta emocion es importante, porque determina por que el usuario tomara accion en este momento.</p><h3 id="_4-3-el-progreso-que-quiere-lograr" tabindex="-1">4.3 El progreso que quiere lograr <a class="header-anchor" href="#_4-3-el-progreso-que-quiere-lograr" aria-label="Permalink to “4.3 El progreso que quiere lograr”">​</a></h3><p>No solo quiere &quot;hacer una accion&quot;, sino a que nuevo estado quiere llevarse?</p><ul><li>De la confusion a la claridad</li><li>De la ansiedad a la tranquilidad</li><li>De la procrastinacion a la accion</li><li>De la ineficiencia a la fluidez</li><li>De no saber explicarse a poder entregar directamente</li></ul><p>En este paso, la palabra &quot;progreso&quot; es clave. Porque lo que mucha gente realmente compra no es una herramienta, sino un <strong>cambio de estado</strong>.</p><h3 id="_4-4-solucion-alternativa-actual" tabindex="-1">4.4 Solucion alternativa actual <a class="header-anchor" href="#_4-4-solucion-alternativa-actual" aria-label="Permalink to “4.4 Solucion alternativa actual”">​</a></h3><p>Sin tu producto, como lo hace ahora?</p><ul><li>Copiar y pegar a mano</li><li>Arreglarselas con Excel o notas</li><li>Pedir ayuda a un colega</li><li>Posponerlo y no hacerlo</li><li>Saltar entre varias herramientas</li></ul><p>Quien sea la solucion alternativa, ese es tu verdadero entorno competitivo.</p><h3 id="_4-5-criterio-de-exito" tabindex="-1">4.5 Criterio de exito <a class="header-anchor" href="#_4-5-criterio-de-exito" aria-label="Permalink to “4.5 Criterio de exito”">​</a></h3><p>Como se sabe que el problema esta realmente resuelto?</p><ul><li>Obtener un resultado compartible en 10 minutos</li><li>Poder enviar a otros sin necesidad de grandes revisiones</li><li>No olvidar, equivocarse ni perderse cosas facilmente</li><li>Saber que hacer a continuacion desde el primer uso</li></ul><p>Si ni siquiera puedes explicar &quot;como juzga el usuario si valio la pena&quot;, entonces esta direccion probablemente aun no esta bien definida.</p><p><a id="jtbd-formula"></a></p><h2 id="_5-formula-de-una-frase-que-puedes-usar-directamente" tabindex="-1"><a href="#top-jtbd">5. Formula de una frase que puedes usar directamente</a> <a class="header-anchor" href="#_5-formula-de-una-frase-que-puedes-usar-directamente" aria-label="Permalink to “5. Formula de una frase que puedes usar directamente”">​</a></h2><p>Cuando quieras organizar una direccion de producto, puedes usar esta formula muy practica:</p><blockquote><p>Cuando __________, quiero __________, para __________.<br> Ahora solo puedo __________ para arreglarmelas con esto.</p></blockquote><p>Por ejemplo:</p><blockquote><p>Cuando termino una reunion de proyecto con mucha informacion, quiero obtener rapidamente un acta con tareas, responsables y fechas limite, para poder sincronizar inmediatamente al equipo y avanzar en la ejecucion.<br> Ahora solo puedo arreglarmelas recordando, revisando el historial de chat y organizando manualmente.</p></blockquote><p>Otro ejemplo:</p><blockquote><p>Cuando me preparo para enviar mi candidatura a un nuevo puesto, quiero reescribir rapidamente mis experiencias en una version mas adaptada al puesto, para poder enviar un curriculum decente con mas confianza.<br> Ahora solo puedo copiar repetidamente mi antiguo curriculum y modificar las formulaciones a mano, hasta que ya no estoy seguro de nada.</p></blockquote><p>Si puedes escribir una frase con este nivel de claridad, el diseno de paginas, el diseno de prompts y la priorizacion de funciones seran mucho mas faciles.</p><h2 id="_6-al-hacer-productos-de-ia-presta-atencion-a-estos-tres-niveles-de-job" tabindex="-1">6. Al hacer productos de IA, presta atencion a estos tres niveles de job <a class="header-anchor" href="#_6-al-hacer-productos-de-ia-presta-atencion-a-estos-tres-niveles-de-job" aria-label="Permalink to “6. Al hacer productos de IA, presta atencion a estos tres niveles de job”">​</a></h2><p>Muchos productos de IA parecen impresionantes en las demos, pero despues de lanzarse no retienen a los usuarios. La razon comun es que solo resuelven la accion superficial, sin resolver el job mas profundo.</p><p>Puedes dividir un job en tres niveles:</p><h3 id="_6-1-nivel-funcional" tabindex="-1">6.1 Nivel funcional <a class="header-anchor" href="#_6-1-nivel-funcional" aria-label="Permalink to “6.1 Nivel funcional”">​</a></h3><p>Cual es la tarea mas superficial?</p><ul><li>Resumir documentos</li><li>Reescribir textos</li><li>Extraer tareas pendientes</li><li>Generar imagenes</li></ul><p>Este es el nivel que los usuarios expresan mas facilmente.</p><h3 id="_6-2-nivel-emocional" tabindex="-1">6.2 Nivel emocional <a class="header-anchor" href="#_6-2-nivel-emocional" aria-label="Permalink to “6.2 Nivel emocional”">​</a></h3><p>Que molestia quiere reducir el usuario, o que sensacion quiere obtener?</p><ul><li>No quiere sentirse tan agobiado</li><li>No quiere parecer poco profesional</li><li>No quiere empezar de cero cada vez</li><li>Quiere sentir mas control</li></ul><p>Mucha disposicion a pagar esta fuertemente relacionada con el nivel emocional.</p><h3 id="_6-3-nivel-social" tabindex="-1">6.3 Nivel social <a class="header-anchor" href="#_6-3-nivel-social" aria-label="Permalink to “6.3 Nivel social”">​</a></h3><p>Como quiere que lo perciban los demas?</p><ul><li>Parecer mas confiable</li><li>Parecer mas organizado en el equipo</li><li>Parecer mas profesional ante los clientes</li><li>Saber expresarse mejor en redes sociales</li></ul><p>Si solo haces el nivel funcional, el producto es facil de reemplazar; si tambien entiendes el nivel emocional y el social, sera mas facil encontrar un valor verdaderamente pegajoso.</p><h2 id="_7-usa-jtbd-para-filtrar-direcciones-de-producto" tabindex="-1">7. Usa JTBD para filtrar direcciones de producto <a class="header-anchor" href="#_7-usa-jtbd-para-filtrar-direcciones-de-producto" aria-label="Permalink to “7. Usa JTBD para filtrar direcciones de producto”">​</a></h2><p>A veces no es que ya tengas un producto, sino que tienes 3 a 5 ideas y no sabes cual hacer. Aqui JTBD es ideal para filtrar.</p><p>Puedes tomar cada idea y preguntarte 5 cosas:</p><ol><li>El escenario correspondiente a esta idea es lo suficientemente concreto?</li><li>El usuario ya esta usando algun metodo torpe para resolverlo?</li><li>El dolor de este job es lo suficientemente fuerte, o lo suficientemente frecuente?</li><li>Si lo hago bien, el usuario sentira claramente que &quot;su estado mejoro&quot;?</li><li>Puedo hacer una primera version solo en torno al paso clave de este job, algo pequeno pero util?</li></ol><p>Si despues de hablar de una direccion solo puedes decir &quot;me parece interesante&quot;, pero no puedes explicar el disparador, la solucion alternativa y el criterio de exito, probablemente sea solo una inspiracion vaga, no una direccion madura.</p><h2 id="_8-preguntas-que-puedes-usar-directamente-para-entrevistar-usuarios" tabindex="-1">8. Preguntas que puedes usar directamente para entrevistar usuarios <a class="header-anchor" href="#_8-preguntas-que-puedes-usar-directamente-para-entrevistar-usuarios" aria-label="Permalink to “8. Preguntas que puedes usar directamente para entrevistar usuarios”">​</a></h2><p>Mucha gente, al hacer investigacion, pregunta: &quot;Que funciones quieres?&quot; Este tipo de pregunta facilmente obtiene respuestas superficiales.</p><p>JTBD es mas adecuado para hacer este tipo de preguntas:</p><ul><li>Cuando fue la ultima vez que encontraste este problema?</li><li>Que estabas haciendo en ese momento, por que te bloqueaste?</li><li>Como lo resolviste al final?</li><li>En este proceso, cual fue la parte mas molesta, mas lenta o que menos confianza te dio?</li><li>Si hubiera una herramienta que te ayudara, que resultado te haria sentir que realmente es util?</li><li>Que metodos alternativos has probado? Por que no fueron lo suficientemente buenos?</li></ul><p>Este tipo de preguntas tiene una ventaja: lleva la conversacion de vuelta a las experiencias reales, en lugar de quedarse en preferencias imaginadas.</p><h2 id="_9-usa-ia-para-ayudarte-con-el-analisis-jtbd" tabindex="-1">9. Usa IA para ayudarte con el analisis JTBD <a class="header-anchor" href="#_9-usa-ia-para-ayudarte-con-el-analisis-jtbd" aria-label="Permalink to “9. Usa IA para ayudarte con el analisis JTBD”">​</a></h2><p>JTBD no fue inventado por la IA, pero la IA es muy adecuada para ayudarte a organizar y refinar JTBD.</p><p>Por ejemplo, si ya has recogido 5 a 10 comentarios de usuarios, puedes pasarlos al modelo y pedirle que los resuma siguiendo esta estructura:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Por favor actua como asistente de investigacion de producto.</span></span>
<span class="line"><span>Te dare algunas citas textuales de usuarios. Por favor no des sugerencias de funciones primero,</span></span>
<span class="line"><span>sino organiza primero siguiendo el marco de Jobs to Be Done:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. En que escenario se encuentra el usuario</span></span>
<span class="line"><span>2. Cual es el evento que detona su accion</span></span>
<span class="line"><span>3. Cual es el progreso que realmente quiere lograr</span></span>
<span class="line"><span>4. Cual es la solucion alternativa actual</span></span>
<span class="line"><span>5. Cual es el criterio de exito que mas le importa</span></span>
<span class="line"><span>6. Que palabras emocionales aparecen repetidamente en estos comentarios</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Finalmente, organiza todo esto en 3 hipotesis JTBD que mas valga la pena verificar primero.</span></span></code></pre></div><p>Si ya tienes una idea, tambien puedes pedir a la IA que te ayude con la primera ronda de convergencia:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Quiero hacer [tu idea de producto].</span></span>
<span class="line"><span>Por favor no me des una lista de funciones directamente, sino analiza usando el metodo Jobs to Be Done:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Que escenarios concretos podria servir este producto</span></span>
<span class="line"><span>2. En cada escenario, cual es el job central que el usuario quiere completar</span></span>
<span class="line"><span>3. Que soluciones alternativas existen actualmente</span></span>
<span class="line"><span>4. Que job es mas adecuado como punto de partida para un MVP, y por que</span></span>
<span class="line"><span>5. Escribe el job final recomendado como una frase JTBD clara</span></span></code></pre></div><p>La ventaja de hacer esto es que no seras arrastrado inmediatamente por la IA a &quot;brainstormear 50 funciones&quot;, sino que primero aclararas la direccion.</p><h2 id="_10-los-4-errores-mas-comunes-de-los-principiantes" tabindex="-1">10. Los 4 errores mas comunes de los principiantes <a class="header-anchor" href="#_10-los-4-errores-mas-comunes-de-los-principiantes" aria-label="Permalink to “10. Los 4 errores mas comunes de los principiantes”">​</a></h2><h3 id="_10-1-escribir-el-job-como-un-nombre-de-funcion" tabindex="-1">10.1 Escribir el job como un nombre de funcion <a class="header-anchor" href="#_10-1-escribir-el-job-como-un-nombre-de-funcion" aria-label="Permalink to “10.1 Escribir el job como un nombre de funcion”">​</a></h3><p>&quot;Resumen con IA&quot;, &quot;clasificacion inteligente&quot;, &quot;generacion automatica&quot; no son jobs, solo son posibles formas de implementacion.</p><h3 id="_10-2-escribir-un-grupo-demasiado-amplio" tabindex="-1">10.2 Escribir un grupo demasiado amplio <a class="header-anchor" href="#_10-2-escribir-un-grupo-demasiado-amplio" aria-label="Permalink to “10.2 Escribir un grupo demasiado amplio”">​</a></h3><p>&quot;Todos los oficinistas&quot;, &quot;todos los estudiantes&quot;, &quot;todos los emprendedores&quot; suelen ser demasiado amplios. Cuanto mas amplio, mas dificil es ver escenarios reales.</p><h3 id="_10-3-solo-escuchar-lo-que-el-usuario-dice-sin-observar-lo-que-hace" tabindex="-1">10.3 Solo escuchar lo que el usuario dice, sin observar lo que hace <a class="header-anchor" href="#_10-3-solo-escuchar-lo-que-el-usuario-dice-sin-observar-lo-que-hace" aria-label="Permalink to “10.3 Solo escuchar lo que el usuario dice, sin observar lo que hace”">​</a></h3><p>El usuario describira lo que quiere, pero sus verdaderas prioridades suelen estar ocultas en como se arregla actualmente para resolver los problemas.</p><h3 id="_10-4-querer-hacer-una-plataforma-completa-desde-el-principio" tabindex="-1">10.4 Querer hacer una plataforma completa desde el principio <a class="header-anchor" href="#_10-4-querer-hacer-una-plataforma-completa-desde-el-principio" aria-label="Permalink to “10.4 Querer hacer una plataforma completa desde el principio”">​</a></h3><p>La forma correcta de usar JTBD normalmente no es &quot;voy a hacer una gran plataforma que haga de todo&quot;, sino primero enfocarse en el paso mas critico de un escenario y hacerlo excepcionalmente bien.</p><h2 id="_11-resumen" tabindex="-1">11. Resumen <a class="header-anchor" href="#_11-resumen" aria-label="Permalink to “11. Resumen”">​</a></h2><p>Lo mas valioso de Jobs to Be Done no es darte un nuevo termino, sino ayudarte a cambiar tu angulo de observacion: <strong>no te centres solo en las funciones del producto, sino en lo que el usuario quiere avanzar al siguiente paso.</strong></p><p>Cuando empieces a preguntarte repetidamente:</p><ul><li>En que escenario contrata el usuario este producto</li><li>Donde se ha quedado bloqueado exactamente</li><li>Que metodo esta usando para arreglarselas</li><li>Despues de resolver el problema, como cambiara su estado</li></ul><p>Descubriras que muchas ideas originalmente vagas se aclaran de repente, y muchas funciones originalmente llamativas dejan de ser tan importantes.</p><p>Hacer productos, especialmente productos de IA, es facil caer en la trampa de obsesionarse con la demostracion de capacidades desde el principio. JTBD te ayuda a devolver la atencion a lo realmente importante: <strong>por que te necesita el usuario, y que progreso le estas ayudando a completar.</strong></p><p><a id="jtbd-ai"></a></p><h2 id="_12-como-usar-la-ia-para-practicar-jtbd" tabindex="-1"><a href="#top-jtbd">12. Como usar la IA para practicar JTBD</a> <a class="header-anchor" href="#_12-como-usar-la-ia-para-practicar-jtbd" aria-label="Permalink to “12. Como usar la IA para practicar JTBD”">​</a></h2><p>JTBD no fue inventado por la IA, pero la IA es muy adecuada para actuar como tu asistente de investigacion, asistente de organizacion y asistente de contraste dentro de este metodo. La clave es: <strong>dejar que la IA te ayude a organizar y expandir, no que adivine por ti lo que piensan los usuarios.</strong></p><p>Puedes usarlo asi:</p><h3 id="_12-1-dejar-que-la-ia-te-ayude-a-reescribir-ideas-vagas-como-hipotesis-jtbd" tabindex="-1">12.1 Dejar que la IA te ayude a reescribir ideas vagas como hipotesis JTBD <a class="header-anchor" href="#_12-1-dejar-que-la-ia-te-ayude-a-reescribir-ideas-vagas-como-hipotesis-jtbd" aria-label="Permalink to “12.1 Dejar que la IA te ayude a reescribir ideas vagas como hipotesis JTBD”">​</a></h3><p>Cuando solo tienes una descripcion vaga en mente, como &quot;quiero hacer una herramienta para ayudar a universitarios a encontrar practicas&quot;, primero puedes pedir a la IA que la descomponga en varios jobs posibles:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Tengo una idea vaga de producto: [tu idea]</span></span>
<span class="line"><span>Por favor no me des una lista de funciones directamente, sino analiza usando el enfoque de Jobs to Be Done:</span></span>
<span class="line"><span>1. A que escenarios concretos podria corresponder</span></span>
<span class="line"><span>2. En cada escenario, cual es el progreso que el usuario realmente quiere lograr</span></span>
<span class="line"><span>3. Cual podria ser la solucion alternativa actual</span></span>
<span class="line"><span>4. Que job es mas adecuado para hacer primero un MVP</span></span>
<span class="line"><span>Finalmente, escribe cada job como una frase JTBD clara.</span></span></code></pre></div><p>Incluso puedes escribir la entrada de forma muy basica:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Quiero hacer algo para ayudar a universitarios a encontrar practicas.</span></span>
<span class="line"><span>No se muy bien que hacer exactamente, ayudame a pensar que es lo que los usuarios realmente quieren lograr.</span></span></code></pre></div><p>La IA podria dar un resultado util como este:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Posibles direcciones JTBD:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Cuando me preparo por primera vez para enviar candidaturas de practicas, quiero saber rapidamente que materiales debo preparar primero,</span></span>
<span class="line"><span>para no estar posponiendo el envio por la confusion de informacion.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Cuando veo una oferta de practicas, quiero juzgar rapidamente si vale la pena aplicar,</span></span>
<span class="line"><span>para no perder demasiado tiempo en puestos que no me convienen.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. Cuando empiezo a enviar candidaturas, quiero adaptar mi curriculum existente a una version mas ajustada al puesto,</span></span>
<span class="line"><span>para poder enviarlo mas rapido y mejorar mi tasa de aprobacion.</span></span></code></pre></div><p>El valor de este tipo de resultado es que descompone tu idea original muy general en varias direcciones mas cercanas a escenarios reales.</p><h3 id="_12-2-dejar-que-la-ia-te-ayude-a-organizar-citas-textuales-de-entrevistas" tabindex="-1">12.2 Dejar que la IA te ayude a organizar citas textuales de entrevistas <a class="header-anchor" href="#_12-2-dejar-que-la-ia-te-ayude-a-organizar-citas-textuales-de-entrevistas" aria-label="Permalink to “12.2 Dejar que la IA te ayude a organizar citas textuales de entrevistas”">​</a></h3><p>Si ya has hecho varias entrevistas con usuarios, puedes pasar las transcripciones a la IA y pedirle que extraiga los escenarios, disparadores, soluciones alternativas y criterios de exito que se repiten.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>A continuacion estan las citas textuales de 5 usuarios.</span></span>
<span class="line"><span>Por favor no des soluciones primero, sino organiza siguiendo el marco JTBD:</span></span>
<span class="line"><span>1. En que escenario se encuentra el usuario</span></span>
<span class="line"><span>2. Cual es el evento que detona su accion</span></span>
<span class="line"><span>3. Cual es el progreso que realmente quiere lograr</span></span>
<span class="line"><span>4. Cual es la solucion alternativa actual</span></span>
<span class="line"><span>5. Cual es el criterio de exito que mas le importa</span></span>
<span class="line"><span>6. Que informacion se repite entre multiples usuarios</span></span>
<span class="line"><span>Finalmente, organiza en 3 hipotesis JTBD que mas valga la pena verificar primero.</span></span></code></pre></div><p>Una entrada simple de principiante tambien podria ser:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Pregunte a 3 personas, y mas o menos dijeron esto:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Cada vez que quiero enviar una practica tengo que rehacer el curriculum, es muy molesto.</span></span>
<span class="line"><span>2. En realidad lo que mas miedo me da es no saber si lo he escrito bien.</span></span>
<span class="line"><span>3. Ahora le pido a companeros de cursos superiores que me lo revisen, pero me da pena molestarles siempre.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Ayudame a organizar, que es lo que realmente quieren lograr.</span></span></code></pre></div><p>La IA podria responder:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Resultado organizado:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Escenario comun: antes de enviar candidaturas de practicas, necesitan trabajar en el curriculum</span></span>
<span class="line"><span>- Dificultad comun: no saben como modificarlo hasta que este &quot;lo suficientemente bien&quot;</span></span>
<span class="line"><span>- Solucion alternativa actual: pedir a companeros de cursos superiores que lo revisen, modificarlo una y otra vez</span></span>
<span class="line"><span>- Posible JTBD:</span></span>
<span class="line"><span>  Cuando me preparo para enviar candidaturas de practicas, quiero juzgar mas rapidamente si mi curriculum ya esta listo para enviar,</span></span>
<span class="line"><span>  para no quedarme atascado en &quot;lo modifico una vez mas&quot; y retrasar el envio indefinidamente.</span></span></code></pre></div><p>Este tipo de resultado es muy util porque te ayuda a extraer de citas textuales dispersas algo que se parece mas a una &quot;necesidad&quot;.</p><h3 id="_12-3-dejar-que-la-ia-haga-una-ronda-ligera-de-investigacion-en-la-red" tabindex="-1">12.3 Dejar que la IA haga una ronda ligera de investigacion en la red <a class="header-anchor" href="#_12-3-dejar-que-la-ia-haga-una-ronda-ligera-de-investigacion-en-la-red" aria-label="Permalink to “12.3 Dejar que la IA haga una ronda ligera de investigacion en la red”">​</a></h3><p>Antes de empezar entrevistas a gran escala, puedes pedir a la IA que haga un barrido de informacion externa muy ligero, como:</p><ul><li>En foros o comunidades publicas, como se queja la gente de este problema</li><li>En el mercado, que nivel de problema resuelven principalmente los productos existentes</li><li>Cual es la solucion alternativa mas comun de los usuarios</li><li>En las resenas comunes, cuales son los puntos que mas satisfaccion y mas insatisfaccion generan</li></ul><p>Esta investigacion no puede sustituir las entrevistas reales con usuarios, pero es ideal como calentamiento en la fase de Discover, ayudandote a construir primero un mapa de problemas.</p><p>Una entrada simple podria ser:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Por favor ayudame a buscar:</span></span>
<span class="line"><span>&quot;Cuales son los puntos de dolor mas comunes cuando los universitarios modifican su curriculum y envian candidaturas de practicas?&quot;</span></span>
<span class="line"><span>Prioriza lo que la gente dice en foros publicos, posts de experiencia y comunidades de busqueda de empleo.</span></span>
<span class="line"><span>Organizalo en 5 problemas mas comunes.</span></span></code></pre></div><p>La IA podria responder:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Puntos de dolor comunes organizados:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. No saber que poner en el curriculum, muy poca experiencia</span></span>
<span class="line"><span>2. No saber como adaptarlo a diferentes puestos</span></span>
<span class="line"><span>3. Modificar muchas versiones pero sin certeza de si es suficientemente bueno</span></span>
<span class="line"><span>4. No encontrar a alguien fiable que lo revise</span></span>
<span class="line"><span>5. El proceso de envio es complicado, facil de procrastinar</span></span></code></pre></div><p>Este tipo de resultado no debe tomarse como conclusion final, pero es ideal para decidir que tipo de problema priorizar en las entrevistas.</p><h3 id="_12-4-dejar-que-la-ia-actue-como-abogado-del-diablo" tabindex="-1">12.4 Dejar que la IA actue como &quot;abogado del diablo&quot; <a class="header-anchor" href="#_12-4-dejar-que-la-ia-actue-como-abogado-del-diablo" aria-label="Permalink to “12.4 Dejar que la IA actue como &quot;abogado del diablo&quot;”">​</a></h3><p>Muchas veces nos encariñamos demasiado con nuestras propias ideas. Puedes pedir especificamente a la IA que asuma el rol de alguien critico, obligandote a explicar el problema mas claramente:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Por favor actua como un consultor de investigacion de producto muy estricto.</span></span>
<span class="line"><span>A continuacion esta mi hipotesis JTBD: [tu hipotesis]</span></span>
<span class="line"><span>Por favor critica desde los siguientes angulos:</span></span>
<span class="line"><span>1. Este escenario es demasiado amplio?</span></span>
<span class="line"><span>2. Este job esta escrito como una funcion en lugar de un progreso real?</span></span>
<span class="line"><span>3. La solucion alternativa es demasiado debil?</span></span>
<span class="line"><span>4. El criterio de exito no es lo suficientemente claro?</span></span>
<span class="line"><span>5. Cual es el riesgo que mas necesita ser verificado en esta hipotesis?</span></span></code></pre></div><p>La ventaja de hacer esto es que descubriras mas rapidamente si estas mirando necesidades o solo estas mirando la solucion que te gusta.</p><h2 id="📚-tareas" tabindex="-1">📚 Tareas <a class="header-anchor" href="#📚-tareas" aria-label="Permalink to “📚 Tareas”">​</a></h2><p>Por favor completa las siguientes tareas basandote en el contenido anterior:</p><ol><li>Elige una idea de producto que quieras hacer recientemente, y escribela claramente usando la formula JTBD</li><li>Completa los 5 elementos para esta idea: escenario, disparador, progreso, solucion alternativa, criterio de exito</li><li>Encuentra 3 usuarios potenciales, y al menos una vez logra preguntar &quot;cuando fue la ultima vez que encontraste este problema&quot;</li><li>Pasa las citas textuales de las entrevistas a la IA, y organiza en 3 hipotesis JTBD que mas valga la pena verificar primero</li></ol><h2 id="lectura-adicional" tabindex="-1">Lectura adicional <a class="header-anchor" href="#lectura-adicional" aria-label="Permalink to “Lectura adicional”">​</a></h2><ul><li><a href="https://www.christenseninstitute.org/theory/jobs-to-be-done/" target="_blank" rel="noreferrer">Christensen Institute: Jobs to Be Done</a></li><li><a href="https://online.hbs.edu/blog/post/jobs-to-be-done" target="_blank" rel="noreferrer">Harvard Business School Online: What Is Jobs to Be Done?</a></li><li><a href="https://www.intercom.com/blog/jobs-to-be-done-framework/" target="_blank" rel="noreferrer">Intercom: Jobs-to-be-Done: A framework for customer needs</a></li><li><a href="https://www.mural.co/blog/jobs-to-be-done-framework" target="_blank" rel="noreferrer">Mural: Jobs to Be Done framework guide</a></li></ul>`,148))])}}});export{b as __pageData,g as default};
